def insert(root, node):
    if root is None:
        return node
    cur = root
    while True:
        if node.end > cur.max_end:
            cur.max_end = node.end
        if node.start < cur.start:
            if cur.left is None:
                cur.left = node
                return root
            cur = cur.left
        else:
